q.push(new A.P("cr_malform",2,"\u0411\u0430\u0433\u0440\u044f\u043d\u044b\u0435 \u0443\u0440\u043e\u0434\u0441\u0442\u0432\u0430","\u041f\u043e \u0436\u0435\u043b\u0430\u043d\u0438\u044e \u0431\u0440\u043e\u0441\u044c\u0442\u0435 \u043a8 \u0438\u043b\u0438 \u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0432\u043d\u0435\u0448\u043d\u044e\u044e \u043c\u0443\u0442\u0430\u0446\u0438\u044e: 1 \u2014 \u0432 \u0414\u0438\u043a\u043e\u043c \u043e\u0431\u043b\u0438\u043a\u0435 \u0442\u0435\u043b\u043e \u0432\u044b\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u0444\u043e\u0440\u043c\u0443 \u0437\u0432\u0435\u0440\u044f; 2 \u2014 \u043b\u0438\u0448\u043d\u044f\u044f \u0440\u0443\u0434\u0438\u043c\u0435\u043d\u0442\u0430\u0440\u043d\u0430\u044f \u043a\u043e\u043d\u0435\u0447\u043d\u043e\u0441\u0442\u044c (\u0438\u043b\u0438 \u0442\u0440\u0438); 3 \u2014 \u0432 \u043f\u043e\u043a\u043e\u0435 \u043c\u0435\u0436\u0434\u0443 \u043a\u043e\u043d\u0435\u0447\u043d\u043e\u0441\u0442\u044f\u043c\u0438 \u043d\u0430\u0440\u0430\u0441\u0442\u0430\u0435\u0442 \u043f\u0430\u0443\u0442\u0438\u043d\u0430 \u0436\u0438\u043b; 4 \u2014 \u0442\u0435\u043b\u043e \u0438\u0437 \u0447\u0430\u0441\u0442\u0435\u0439 \u0440\u0430\u0437\u043d\u044b\u0445 \u0436\u0438\u0432\u043e\u0442\u043d\u044b\u0445; 5 \u2014 \u0432\u0435\u0449\u0438 \u043d\u0430 \u0432\u0430\u0441 \u043e\u0431\u0440\u0430\u0441\u0442\u0430\u044e\u0442 \u0436\u0438\u043b\u0430\u043c\u0438, \u0433\u043b\u0430\u0437\u0430\u043c\u0438 \u0438 \u0432\u0435\u043d\u0430\u043c\u0438; 6 \u2014 \u043a\u043e\u0436\u0430 \u0441\u043e\u0448\u043b\u0430, \u0432\u0438\u0434\u043d\u044b \u043c\u044b\u0448\u0446\u044b (\u0431\u0435\u0437\u0431\u043e\u043b\u0435\u0437\u043d\u0435\u043d\u043d\u043e); 7 \u2014 \u0432\u0441\u0451, \u0447\u0435\u0433\u043e \u0432\u044b \u043a\u0430\u0441\u0430\u0435\u0442\u0435\u0441\u044c, \u043f\u0430\u0447\u043a\u0430\u0435\u0442\u0441\u044f \u043a\u0440\u043e\u0432\u044c\u044e; 8 \u2014 \u0440\u043e\u0442 \u0437\u0430\u0440\u043e\u0441 \u043e\u043f\u0443\u0445\u043e\u043b\u044c\u044e, \u043d\u043e \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u0434\u0432\u0430 \u0434\u0440\u0443\u0433\u0438\u0445.",!0))
q.push(new A.P("cr_limb",2,"\u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u0435 \u043a\u043e\u043d\u0435\u0447\u043d\u043e\u0441\u0442\u0435\u0439","\u041e\u0442\u0440\u0443\u0431\u043b\u0435\u043d\u043d\u044b\u0435 \u0447\u0430\u0441\u0442\u0438 \u0442\u0435\u043b\u0430 \u043e\u0442\u0440\u0430\u0441\u0442\u0430\u044e\u0442 \u0437\u0430 1\u043a10 \u0434\u043d\u0435\u0439 \u0438 \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442 \u043f\u0440\u0435\u0436\u043d\u0438\u0435 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430. \u0412\u044b \u043d\u0435 \u043c\u043e\u0436\u0435\u0442\u0435 \u043d\u0430\u0432\u0441\u0435\u0433\u0434\u0430 \u043b\u0438\u0448\u0438\u0442\u044c\u0441\u044f \u043a\u043e\u043d\u0435\u0447\u043d\u043e\u0441\u0442\u0438 \u0438\u043b\u0438 \u043e\u0440\u0433\u0430\u043d\u0430.",!0))
q.push(new A.P("cr_spells",2,"\u0417\u0430\u043a\u043b\u0438\u043d\u0430\u043d\u0438\u044f \u043a\u0440\u0443\u0433\u0430","\u0417\u0430\u0433\u043e\u0432\u043e\u0440 \xab\u041f\u0435\u0440\u0432\u043e\u0431\u044b\u0442\u043d\u0430\u044f \u0434\u0438\u043a\u043e\u0441\u0442\u044c\xbb (\u043d\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u0432 \u0447\u0438\u0441\u043b\u0435 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u0445). \u0412\u0441\u0435\u0433\u0434\u0430 \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043b\u0435\u043d\u044b: 3 \u0443\u0440\u043e\u0432\u0435\u043d\u044c \u2014 \xab\u0418\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u0441\u0435\u0431\u044f\xbb, \xab\u0423\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u0438\u0435/\u0443\u043c\u0435\u043d\u044c\u0448\u0435\u043d\u0438\u0435\xbb; 5 \u2014 \xab\u041c\u0430\u0441\u0441\u043e\u0432\u043e\u0435 \u043b\u0435\u0447\u0430\u0449\u0435\u0435 \u0441\u043b\u043e\u0432\u043e\xbb, \xab\u0412\u043e\u0437\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435\xbb; 7 \u2014 \xab\u0427\u0451\u0440\u043d\u044b\u0435 \u0449\u0443\u043f\u0430\u043b\u044c\u0446\u0430\xbb, \xab\u041a\u0430\u043c\u0435\u043d\u043d\u0430\u044f \u043a\u043e\u0436\u0430\xbb; 9 \u2014 \xab\u0410\u043d\u0442\u0438\u0436\u0438\u0437\u043d\u0435\u043d\u043d\u0430\u044f \u043e\u0431\u043e\u043b\u043e\u0447\u043a\u0430\xbb, \xab\u041c\u0430\u0441\u0441\u043e\u0432\u043e\u0435 \u043b\u0435\u0447\u0435\u043d\u0438\u0435 \u0440\u0430\u043d\xbb.",!0))
q.push(new A.P("cr_gruesome",2,"\u0416\u0443\u0442\u043a\u043e\u0435 \u043f\u0440\u0435\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u0435","\u0411\u043e\u043d\u0443\u0441\u043d\u044b\u043c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043c \u0442\u0440\u0430\u0442\u0438\u0442\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u0414\u0438\u043a\u043e\u0433\u043e \u043e\u0431\u043b\u0438\u043a\u0430 \u0438 \u043c\u0443\u0442\u0438\u0440\u0443\u0435\u0442\u0435, \u043e\u0441\u0442\u0430\u0432\u0430\u044f\u0441\u044c \u0441\u043e\u0431\u043e\u0439 (\u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440\u0438\u0441\u0442\u0438\u043a\u0438, \u0445\u0438\u0442\u044b \u0438 \u0437\u0430\u043a\u043b\u0438\u043d\u0430\u043d\u0438\u044f \u2014 \u0432\u0430\u0448\u0438). \u0414\u043b\u0438\u0442\u0441\u044f \u0441\u0442\u043e\u043b\u044c\u043a\u043e \u0436\u0435, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0414\u0438\u043a\u0438\u0439 \u043e\u0431\u043b\u0438\u043a; \u0437\u0430\u043a\u0430\u043d\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0434\u043e\u0441\u0440\u043e\u0447\u043d\u043e \u0431\u043e\u043d\u0443\u0441\u043d\u044b\u043c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043c, \u0435\u0441\u043b\u0438 \u0432\u044b \u043d\u0435\u0434\u0435\u0435\u0441\u043f\u043e\u0441\u043e\u0431\u043d\u044b \u0438\u043b\u0438 \u0443\u043c\u0438\u0440\u0430\u0435\u0442\u0435.\n\u2022 \u0412\u0445\u043e\u0434: \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0430 \u043d\u0430 \u0432\u0430\u0448 \u0432\u044b\u0431\u043e\u0440 \u0432 10 \u0444\u0442 \u0434\u0435\u043b\u0430\u044e\u0442 \u0441\u043f\u0430\u0441\u0431\u0440\u043e\u0441\u043e\u043a \u041c\u0443\u0434\u0440\u043e\u0441\u0442\u0438 \u043f\u0440\u043e\u0442\u0438\u0432 \u0421\u041b \u0432\u0430\u0448\u0438\u0445 \u0437\u0430\u043a\u043b\u0438\u043d\u0430\u043d\u0438\u0439 \u0438\u043b\u0438 \u0438\u0441\u043f\u0443\u0433\u0430\u043d\u044b \u0434\u043e \u043a\u043e\u043d\u0446\u0430 \u0432\u0430\u0448\u0435\u0433\u043e \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u0433\u043e \u0445\u043e\u0434\u0430.\n\u2022 \u041a\u043e\u0441\u0442\u044f\u043d\u0430\u044f \u0431\u0440\u043e\u043d\u044f: \u0431\u0435\u0437 \u0434\u043e\u0441\u043f\u0435\u0445\u043e\u0432 \u0432\u0430\u0448 \u041a\u0414 = 13 + \u043c\u043e\u0434. \u0422\u0435\u043b\u043e\u0441\u043b\u043e\u0436\u0435\u043d\u0438\u044f (\u0449\u0438\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043d).\n\u2022 \u041c\u0443\u0442\u0438\u0440\u043e\u0432\u0430\u0432\u0448\u0438\u0435 \u0443\u0434\u0430\u0440\u044b: \u043a\u043e\u0433\u0442\u0438, \u0448\u0438\u043f\u044b \u0438\u043b\u0438 \u043f\u0430\u0441\u0442\u044c \u2014 \u0440\u0443\u043a\u043e\u043f\u0430\u0448\u043d\u043e\u0435 \u043e\u0440\u0443\u0436\u0438\u0435, \u043a\u043e\u0442\u043e\u0440\u044b\u043c \u0432\u044b \u0432\u043b\u0430\u0434\u0435\u0435\u0442\u0435; 1\u043a6 + \u043c\u043e\u0434. \u0421\u0438\u043b\u044b \u0438\u043b\u0438 \u041c\u0443\u0434\u0440\u043e\u0441\u0442\u0438 \u0440\u0443\u0431\u044f\u0449\u0435\u0433\u043e \u0438\u043b\u0438 \u043a\u043e\u043b\u044e\u0449\u0435\u0433\u043e \u0443\u0440\u043e\u043d\u0430.\n\u2022 \u041f\u043b\u043e\u0442\u044c-\u0440\u0435\u0437\u0435\u0440\u0432: \u0432\u044b \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442\u0435 \u0432\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0435 \u0445\u0438\u0442\u044b, \u0440\u0430\u0432\u043d\u044b\u0435 \u0443\u0434\u0432\u043e\u0435\u043d\u043d\u043e\u043c\u0443 \u0443\u0440\u043e\u0432\u043d\u044e \u0434\u0440\u0443\u0438\u0434\u0430.\n\u2022 \u0412 \u043f\u0440\u0435\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u0438 \u043c\u043e\u0436\u043d\u043e \u043a\u043e\u043b\u0434\u043e\u0432\u0430\u0442\u044c; \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u044b \u0431\u0435\u0437 \u0446\u0435\u043d\u044b \u043c\u043e\u0436\u043d\u043e \u043d\u0435 \u0434\u0435\u0440\u0436\u0430\u0442\u044c \u0432 \u0440\u0443\u043a\u0430\u0445.",!0))
q.push(new A.P("cr_curse",2,"\u041f\u0440\u043e\u043a\u043b\u044f\u0442\u0438\u0435 \u043f\u043b\u043e\u0442\u0438","\u0420\u0430\u0437 \u0432 \u0445\u043e\u0434, \u043f\u043e\u043f\u0430\u0432 \u043c\u0443\u0442\u0438\u0440\u043e\u0432\u0430\u0432\u0448\u0438\u043c \u0443\u0434\u0430\u0440\u043e\u043c, \u043c\u043e\u0436\u043d\u043e \u043d\u0430\u043b\u043e\u0436\u0438\u0442\u044c \u043d\u0430 \u0446\u0435\u043b\u044c \u043f\u0440\u043e\u043a\u043b\u044f\u0442\u0438\u0435 \u043d\u0430 1 \u043c\u0438\u043d\u0443\u0442\u0443 (\u043d\u0430 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0435 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u0434\u043d\u043e \u0432\u0430\u0448\u0435 \u043f\u0440\u043e\u043a\u043b\u044f\u0442\u0438\u0435, \u043d\u043e\u0432\u043e\u0435 \u0437\u0430\u043c\u0435\u043d\u044f\u0435\u0442 \u0441\u0442\u0430\u0440\u043e\u0435). \u0418\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0439 \u2014 \u0431\u043e\u043d\u0443\u0441 \u043c\u0430\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u0430 \u0437\u0430 \u0434\u043b\u0438\u043d\u043d\u044b\u0439 \u043e\u0442\u0434\u044b\u0445; \u0435\u0449\u0451 \u043e\u0434\u043d\u043e \u043c\u043e\u0436\u043d\u043e \u0432\u0435\u0440\u043d\u0443\u0442\u044c, \u043f\u043e\u0442\u0440\u0430\u0442\u0438\u0432 \u044f\u0447\u0435\u0439\u043a\u0443 1 \u043a\u0440\u0443\u0433\u0430 \u0438\u043b\u0438 \u0432\u044b\u0448\u0435.\n\u2022 \u041f\u0440\u043e\u043a\u043b\u044f\u0442\u0438\u0435 \u0441\u0443\u0445\u043e\u0436\u0438\u043b\u0438\u0439: \u0441\u043a\u043e\u0440\u043e\u0441\u0442\u044c \u0446\u0435\u043b\u0438 \u221210 \u0444\u0442; \u043a\u0430\u0436\u0434\u044b\u0439 \u0440\u0430\u0437, \u043f\u043e\u043f\u0430\u0432 \u0430\u0442\u0430\u043a\u043e\u0439, \u0446\u0435\u043b\u044c \u0434\u0435\u043b\u0430\u0435\u0442 \u0441\u043f\u0430\u0441\u0431\u0440\u043e\u0441\u043e\u043a \u0421\u0438\u043b\u044b \u043f\u0440\u043e\u0442\u0438\u0432 \u0421\u041b \u0432\u0430\u0448\u0438\u0445 \u0437\u0430\u043a\u043b\u0438\u043d\u0430\u043d\u0438\u0439 \u0438\u043b\u0438 \u043f\u0430\u0434\u0430\u0435\u0442 \u043d\u0438\u0447\u043a\u043e\u043c.\n\u2022 \u041f\u0440\u043e\u043a\u043b\u044f\u0442\u0438\u0435 \u043c\u0438\u0433\u0440\u0435\u043d\u0435\u0439: \u0432 \u043d\u0430\u0447\u0430\u043b\u0435 \u0441\u0432\u043e\u0435\u0433\u043e \u0445\u043e\u0434\u0430 \u0446\u0435\u043b\u044c \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442 1\u043a6 \u043f\u0441\u0438\u0445\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0443\u0440\u043e\u043d\u0430 (2\u043a6 \u0441 6 \u0443\u0440\u043e\u0432\u043d\u044f, 3\u043a6 \u0441 10, 4\u043a6 \u0441 14). \u0412 \u043a\u043e\u043d\u0446\u0435 \u0441\u0432\u043e\u0435\u0433\u043e \u0445\u043e\u0434\u0430 \u043e\u043d\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0435\u0442 \u0441\u043f\u0430\u0441\u0431\u0440\u043e\u0441\u043e\u043a \u0422\u0435\u043b\u043e\u0441\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0438 \u043f\u0440\u0438 \u0443\u0441\u043f\u0435\u0445\u0435 \u0441\u043d\u0438\u043c\u0430\u0435\u0442 \u043f\u0440\u043e\u043a\u043b\u044f\u0442\u0438\u0435.",!0))
q.push(new A.P("cr_training",2,"\u041e\u0440\u0433\u0430\u043d\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0431\u043e\u0435\u0432\u0430\u044f \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430","\u0412 \u0416\u0443\u0442\u043a\u043e\u043c \u043f\u0440\u0435\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u0438, \u0441\u043e\u0432\u0435\u0440\u0448\u0438\u0432 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0410\u0442\u0430\u043a\u0430, \u043c\u043e\u0436\u043d\u043e \u0431\u043e\u043d\u0443\u0441\u043d\u044b\u043c \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043c \u043d\u0430\u043d\u0435\u0441\u0442\u0438 \u0435\u0449\u0451 \u043e\u0434\u0438\u043d \u043c\u0443\u0442\u0438\u0440\u043e\u0432\u0430\u0432\u0448\u0438\u0439 \u0443\u0434\u0430\u0440. \u0410\u0442\u0430\u043a\u0438 \u043c\u0443\u0442\u0438\u0440\u043e\u0432\u0430\u0432\u0448\u0438\u043c\u0438 \u0443\u0434\u0430\u0440\u0430\u043c\u0438 \u043c\u043e\u0433\u0443\u0442 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u041c\u0443\u0434\u0440\u043e\u0441\u0442\u044c \u0432\u043c\u0435\u0441\u0442\u043e \u0421\u0438\u043b\u044b.",!0))
q.push(new A.P("cr_mutation",6,"\u0423\u0436\u0430\u0441\u043d\u0430\u044f \u043c\u0443\u0442\u0430\u0446\u0438\u044f","\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u043e\u0434\u043d\u0443 \u043c\u0443\u0442\u0430\u0446\u0438\u044e (\u0441\u043c\u0435\u043d\u0438\u0442\u044c \u043c\u043e\u0436\u043d\u043e, \u043f\u043e\u0442\u0440\u0430\u0442\u0438\u0432 1\u043a10 \u0434\u043d\u0435\u0439 \u043d\u0430 \u043f\u0435\u0440\u0435\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u0435):\n\u2022 \u0420\u0430\u0437\u0440\u043e\u0441\u0448\u0435\u0435\u0441\u044f \u0442\u0435\u043b\u043e: \u0434\u0432\u0435 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0440\u0443\u043a\u0438. \u0418\u043c\u0438 \u043c\u043e\u0436\u043d\u043e \u0434\u0435\u0440\u0436\u0430\u0442\u044c \u0449\u0438\u0442, \u0444\u043e\u043a\u0443\u0441\u0438\u0440\u043e\u0432\u043a\u0443 \u0438\u043b\u0438 \u043f\u0440\u0435\u0434\u043c\u0435\u0442, \u0434\u0430\u0432\u0430\u0442\u044c \u0441\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u044b \u0438 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u0441 \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u0430\u043c\u0438; \u0430\u0442\u0430\u043a\u043e\u0432\u0430\u0442\u044c \u0438\u043c\u0438 \u043e\u0440\u0443\u0436\u0438\u0435\u043c \u043d\u0435\u043b\u044c\u0437\u044f.\n\u2022 \u0412\u0435\u0447\u043d\u043e \u043c\u0435\u043d\u044f\u044e\u0449\u0430\u044f\u0441\u044f \u043f\u043b\u043e\u0442\u044c: \xab\u0418\u0437\u043c\u0435\u043d\u0435\u043d\u0438\u0435 \u0441\u0435\u0431\u044f\xbb \u043d\u0430 \u0441\u0435\u0431\u044f \u2014 \u0431\u0435\u0437 \u044f\u0447\u0435\u0439\u043a\u0438 \u0438 \u043a\u043e\u043d\u0446\u0435\u043d\u0442\u0440\u0430\u0446\u0438\u0438, \u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0443\u0433\u043e\u0434\u043d\u043e; \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e \u043d\u0430 \u0441\u043f\u0430\u0441\u0431\u0440\u043e\u0441\u043a\u0438 \u043f\u0440\u043e\u0442\u0438\u0432 \u043e\u043a\u0430\u043c\u0435\u043d\u0435\u043d\u0438\u044f \u0438 \u043f\u0440\u0435\u0432\u0440\u0430\u0449\u0435\u043d\u0438\u044f.\n\u2022 \u041d\u0435\u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u0430\u044f \u043f\u0441\u0438\u0445\u0438\u043a\u0430: \u0441\u043e\u043f\u0440\u043e\u0442\u0438\u0432\u043b\u0435\u043d\u0438\u0435 \u043f\u0441\u0438\u0445\u0438\u0447\u0435\u0441\u043a\u043e\u043c\u0443 \u0443\u0440\u043e\u043d\u0443, \u043f\u0440\u0435\u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e \u043d\u0430 \u0441\u043f\u0430\u0441\u0431\u0440\u043e\u0441\u043a\u0438 \u0418\u043d\u0442\u0435\u043b\u043b\u0435\u043a\u0442\u0430; \u0432\u0430\u0448\u0438 \u043c\u044b\u0441\u043b\u0438 \u043d\u0435\u043b\u044c\u0437\u044f \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0442\u044c \u043f\u0440\u043e\u0442\u0438\u0432 \u0432\u0430\u0448\u0435\u0439 \u0432\u043e\u043b\u0438.",!0))
